// Auto-loads the 3D Tiles tileset generated by citydb-3dtiler so the viewer
// shows the imported city model without adding the layer by hand in the
// "Add / Configure Layer" panel. The URL can be overridden with ?tileset=<url>.
(function () {
    var params = new URLSearchParams(window.location.search);
    var TILESET_URL = params.get("tileset") || "/tiles/tileset.json";

    function whenReady(callback) {
        if (typeof webMap === "undefined" || typeof Cesium3DTilesDataLayer === "undefined") {
            setTimeout(function () { whenReady(callback); }, 200);
            return;
        }
        callback();
    }

    // Without this the viewer would just show an empty globe.
    function showNoTilesNotice() {
        var el = document.createElement("div");
        el.style.cssText =
            "position:absolute;bottom:64px;left:50%;transform:translateX(-50%);z-index:9999;" +
            "background:rgba(30,41,59,.9);color:#f8fafc;padding:8px 14px;border-radius:6px;" +
            "font:13px/1.4 sans-serif;text-align:center;max-width:80%;";
        el.textContent =
            "No 3D tiles yet — press “Refresh 3D tiles” above the viewer to generate them.";
        document.body.appendChild(el);
    }

    async function autoLoad() {
        try {
            var resp = await fetch(TILESET_URL, { method: "HEAD" });
            if (!resp.ok) {
                console.warn("[auto-load-tileset] " + TILESET_URL + " not reachable (HTTP " +
                    resp.status + ") — run tile generation first.");
                showNoTilesNotice();
                return;
            }
        } catch (err) {
            console.warn("[auto-load-tileset] cannot reach " + TILESET_URL + ":", err);
            showNoTilesNotice();
            return;
        }

        var layer = new Cesium3DTilesDataLayer({
            url: TILESET_URL,
            name: "City Model",
            active: true,
            layerClampToGround: false,
            minLodPixels: 140,
            maxLodPixels: Number.MAX_VALUE,
            maxSizeOfCachedTiles: 200,
            maxCountOfVisibleTiles: 200,
            maximumScreenSpaceError: 16,
        });

        var indicator = document.getElementById("loadingIndicator");
        if (indicator) indicator.style.display = "block";
        try {
            var addedLayer = await Promise.resolve(webMap.addLayer(layer, createInfoTable));
            addLayerToList(addedLayer);
            webMap._activeLayer = addedLayer;
            console.log("[auto-load-tileset] tileset loaded OK");
            // Fire-and-forget: flyTo promises have been observed to never settle,
            // so the loading indicator must not wait on them.
            // Same "zoom to this layer" effect as double-clicking City Model in the
            // layer list (Cesium3DTilesDataLayer.zoomToStartPosition ->
            // flyToBoundingSphere(tileset.boundingSphere)) — the tileset's own bounding
            // sphere is exactly what's on screen, no separate query needed. A shared
            // link carries its own camera, so don't override it.
            if (!params.has("latitude") && !params.has("longitude")) {
                addedLayer.zoomToStartPosition();
            }
            // The toolbar's Home button returns to the same view.
            try {
                cesiumViewer.homeButton.viewModel.command.beforeExecute.addEventListener(function (ev) {
                    ev.cancel = true;
                    addedLayer.zoomToStartPosition();
                });
            } catch (err) {
                console.warn("[auto-load-tileset] could not hook the Home button:", err);
            }
        } catch (err) {
            console.error("[auto-load-tileset] failed to load tileset:", err);
        } finally {
            if (indicator) indicator.style.display = "none";
        }
    }

    whenReady(autoLoad);
})();
